B.R2=new A.cS("next_action",B.aJ)
B.QD=new A.cS("next_action_owner",B.aJ)
B.R_=new A.cS("last_progress_at",B.c5)
B.a2S=s([B.fR,B.v_,B.QJ,B.v0,B.QI,B.QH,B.QV,B.QG,B.R2,B.QD,B.R_,B.fS,B.fT,B.fU],t.gk)
B.acW=new A.v1("folders",B.a2S)
