B.ao7=new A.G(378,B.Wc)
B.a2m=s(["Fixed: turning On really shows no note now \u2014 the session opens directly in \u201clistening for commands\u201d from the first frame, instead of briefly popping a blank note."],t.s)
B.apn=new A.G(377,B.a2m)
